guided.solution:
CREATE TABLE stg_items (item_id int, price_cents int);
CREATE TABLE items_clean (item_id int PRIMARY KEY, price_cents int);
INSERT INTO stg_items VALUES (1, 500), (2, 700), (3, 1000);
TRUNCATE items_clean;
INSERT INTO items_clean SELECT item_id, price_cents FROM stg_items;
TRUNCATE items_clean;
INSERT INTO items_clean SELECT item_id, price_cents FROM stg_items;
SELECT COUNT(*) AS rows, SUM(price_cents) AS total_cents FROM items_clean;
